import { useEffect, useMemo, useState } from 'react'
import {
  ArrowRight,
  Check,
  ChevronDown,
  Clock3,
  Globe2,
  Minus,
  Plus,
  Search,
  Settings2,
  Sparkles,
  SunMedium,
  X,
} from 'lucide-react'
import { CITIES, DEFAULT_CITY_IDS, getCity, type City } from './data/cities'
import {
  countryFlag,
  formatHour,
  formatHourRange,
  formatOffset,
  getCityCellMap,
  getOffsetMinutes,
  getRanges,
  getTodayLabel,
  isAwake,
  type TimeCell,
} from './lib/timezone'
import './styles.css'

type Mode = 'meeting' | 'base'
type TimeFormat = '12h' | '24h'

type AppState = {
  cityIds: string[]
  mode: Mode
  wakeHour: number
  sleepHour: number
  timeFormat: TimeFormat
}

type CityRow = {
  city: City
  cells: TimeCell[]
  offset: number
  overlapHours: Set<number>
}

const DEFAULT_STATE: AppState = {
  cityIds: DEFAULT_CITY_IDS,
  mode: 'meeting',
  wakeHour: 7,
  sleepHour: 23,
  timeFormat: '12h',
}

const STORAGE_KEY = 'gpt-5-6-luna-timezone-checker'

function readStoredState(): AppState {
  if (typeof window === 'undefined') return DEFAULT_STATE
  try {
    const parsed = JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? 'null') as Partial<AppState> | null
    const cityIds = Array.isArray(parsed?.cityIds)
      ? parsed.cityIds.filter((id): id is string => typeof id === 'string' && Boolean(getCity(id)))
      : DEFAULT_STATE.cityIds
    return {
      cityIds: cityIds.length ? [...new Set(cityIds)] : DEFAULT_STATE.cityIds,
      mode: parsed?.mode === 'base' ? 'base' : 'meeting',
      wakeHour: typeof parsed?.wakeHour === 'number' && parsed.wakeHour >= 0 && parsed.wakeHour <= 23 ? parsed.wakeHour : DEFAULT_STATE.wakeHour,
      sleepHour: typeof parsed?.sleepHour === 'number' && parsed.sleepHour >= 0 && parsed.sleepHour <= 23 ? parsed.sleepHour : DEFAULT_STATE.sleepHour,
      timeFormat: parsed?.timeFormat === '24h' ? '24h' : '12h',
    }
  } catch {
    return DEFAULT_STATE
  }
}

function getRangeLabel(start: number, end: number, format: TimeFormat): string {
  return formatHourRange(start, end, format)
}

function getRangeLabels(hours: Set<number>, format: TimeFormat): string[] {
  return getRanges([...hours]).map(({ start, end }) => getRangeLabel(start, end, format))
}

function modeDescription(mode: Mode): string {
  return mode === 'meeting'
    ? 'Find the hours everyone can be awake at once.'
    : 'Compare each city independently against your reference.'
}

function HourCell({ cell, hour, format }: { cell: TimeCell; hour: number; format: TimeFormat }) {
  const status = cell.overlap && cell.awake ? 'overlap' : cell.awake ? 'awake' : 'sleeping'
  const title = `${formatHour(hour, format)} reference · ${cell.label} local · ${status === 'overlap' ? 'overlap' : status === 'awake' ? 'awake' : 'sleeping'}`

  return (
    <div className={`hour-cell ${status}`} title={title} aria-label={title}>
      <span>{cell.label}</span>
      {status === 'overlap' && <Check size={12} strokeWidth={2.8} aria-hidden="true" />}
    </div>
  )
}

function OverlapSummary({
  mode,
  referenceCity,
  rows,
  overlapByCity,
  cityIds,
  format,
}: {
  mode: Mode
  referenceCity: City
  rows: CityRow[]
  overlapByCity: Map<string, Set<number>>
  cityIds: string[]
  format: TimeFormat
}) {
  if (cityIds.length < 2) {
    return (
      <section className="summary-card summary-card--quiet" aria-label="Overlap summary">
        <div className="summary-icon"><Globe2 size={18} /></div>
        <div>
          <p className="summary-kicker">One city selected</p>
          <p className="summary-copy">Add another city to see shared awake hours.</p>
        </div>
        <ArrowRight className="summary-arrow" size={18} aria-hidden="true" />
      </section>
    )
  }

  if (mode === 'meeting') {
    const overlap = overlapByCity.get('meeting') ?? new Set<number>()
    const ranges = getRangeLabels(overlap, format)
    return (
      <section className={`summary-card ${overlap.size ? 'summary-card--active' : 'summary-card--warning'}`} aria-label="Meeting overlap summary">
        <div className="summary-icon"><Sparkles size={18} /></div>
        <div className="summary-main">
          <p className="summary-kicker">Shared availability · Meeting mode</p>
          <div className="summary-line">
            <strong>{overlap.size} {overlap.size === 1 ? 'hour' : 'hours'}</strong>
            <span>everyone is awake in {referenceCity.name}</span>
          </div>
          {overlap.size ? (
            <div className="range-list">
              {ranges.map((range) => <span className="range-pill" key={range}>{range}</span>)}
            </div>
          ) : (
            <p className="warning-copy">No common awake window. Try widening the awake window or switching to Base mode.</p>
          )}
        </div>
        <div className="summary-side-stat"><span>ANCHOR</span><strong>{referenceCity.name}</strong></div>
      </section>
    )
  }

  const nonReferenceRows = rows.filter((row) => row.city.id !== referenceCity.id)
  return (
    <section className="base-summary" aria-label="Base mode overlap summary">
      <div className="base-summary-heading">
        <div>
          <p className="summary-kicker">Independent availability · Base mode</p>
          <p className="base-summary-copy">Each line compares against <strong>{referenceCity.name}</strong>.</p>
        </div>
        <span className="base-summary-ref"><span className="ref-dot" /> {referenceCity.name} is base</span>
      </div>
      <div className="base-summary-list">
        {nonReferenceRows.map((row) => {
          const overlap = overlapByCity.get(row.city.id) ?? new Set<number>()
          const ranges = getRangeLabels(overlap, format)
          return (
            <div className={`base-summary-row ${overlap.size ? '' : 'base-summary-row--warning'}`} key={row.city.id}>
              <div className="base-city-label"><span className="city-swatch" style={{ backgroundColor: row.city.accent }} /> <strong>{row.city.name}</strong><span>{countryFlag(row.city.countryCode)}</span></div>
              {overlap.size ? (
                <div className="base-summary-detail"><strong>{overlap.size}h overlap</strong>{ranges.map((range) => <span className="range-pill range-pill--small" key={range}>{range}</span>)}</div>
              ) : <span className="base-warning-text">No overlap — adjust the window</span>}
            </div>
          )
        })}
      </div>
    </section>
  )
}

function CityPicker({ selectedIds, onAdd }: { selectedIds: string[]; onAdd: (cityId: string) => void }) {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const availableCities = CITIES.filter((city) => !selectedIds.includes(city.id))
  const filteredCities = availableCities.filter((city) => `${city.name} ${city.country} ${city.region}`.toLowerCase().includes(query.toLowerCase()))
  const grouped = filteredCities.reduce<Record<string, City[]>>((acc, city) => {
    acc[city.region] ??= []
    acc[city.region].push(city)
    return acc
  }, {})

  useEffect(() => {
    if (!open) setQuery('')
  }, [open])

  return (
    <div className="picker-wrap">
      <button className="add-city-button" onClick={() => setOpen((value) => !value)} aria-expanded={open}>
        <Plus size={16} strokeWidth={2.5} /> Add city <ChevronDown size={15} className={open ? 'rotate-180' : ''} />
      </button>
      {open && (
        <div className="city-picker" role="dialog" aria-label="Add a city">
          <div className="picker-search"><Search size={15} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search cities or countries" /></div>
          <div className="picker-list">
            {Object.entries(grouped).map(([region, cities]) => (
              <div key={region} className="picker-region">
                <div className="picker-region-label">{region}</div>
                {cities.map((city) => (
                  <button className="picker-option" key={city.id} onClick={() => { onAdd(city.id); setOpen(false) }}>
                    <span className="picker-flag">{countryFlag(city.countryCode)}</span>
                    <span><strong>{city.name}</strong><small>{city.country}</small></span>
                    <Plus size={15} />
                  </button>
                ))}
              </div>
            ))}
            {!filteredCities.length && <p className="picker-empty">No cities match that search.</p>}
          </div>
        </div>
      )}
    </div>
  )
}

function SettingsDrawer({ state, onChange, onClose }: { state: AppState; onChange: (next: Partial<AppState>) => void; onClose: () => void }) {
  const hours = Array.from({ length: 24 }, (_, hour) => hour)
  return (
    <div className="drawer-layer" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}>
      <aside className="settings-drawer" role="dialog" aria-modal="true" aria-labelledby="settings-title">
        <div className="drawer-header">
          <div><p className="eyebrow">Personal schedule</p><h2 id="settings-title">Awake window</h2></div>
          <button className="icon-button" onClick={onClose} aria-label="Close settings"><X size={18} /></button>
        </div>
        <p className="drawer-intro">Use one shared sleep schedule for every city in the comparison.</p>
        <div className="setting-block">
          <label htmlFor="wake-hour">Wake-up hour</label>
          <div className="select-wrap"><SunMedium size={16} /><select id="wake-hour" value={state.wakeHour} onChange={(event) => onChange({ wakeHour: Number(event.target.value) })}>{hours.map((hour) => <option key={hour} value={hour}>{formatHour(hour, state.timeFormat)}</option>)}</select><ChevronDown size={15} /></div>
        </div>
        <div className="setting-block">
          <label htmlFor="sleep-hour">Sleep hour</label>
          <div className="select-wrap"><Clock3 size={16} /><select id="sleep-hour" value={state.sleepHour} onChange={(event) => onChange({ sleepHour: Number(event.target.value) })}>{hours.map((hour) => <option key={hour} value={hour}>{formatHour(hour, state.timeFormat)}</option>)}</select><ChevronDown size={15} /></div>
        </div>
        <div className="setting-block">
          <span className="setting-label">Time format</span>
          <div className="format-toggle" role="group" aria-label="Time format">
            {(['12h', '24h'] as TimeFormat[]).map((format) => <button key={format} className={state.timeFormat === format ? 'active' : ''} onClick={() => onChange({ timeFormat: format })}>{format}</button>)}
          </div>
        </div>
        <div className="schedule-preview"><div className="schedule-preview-top"><span>Current window</span><strong>{formatHour(state.wakeHour, state.timeFormat)} — {formatHour(state.sleepHour, state.timeFormat)}</strong></div><div className="schedule-track"><div className="schedule-track-fill" style={{ left: `${state.wakeHour / 24 * 100}%`, width: `${((state.sleepHour - state.wakeHour + 24) % 24 || 24) / 24 * 100}%` }} /></div><div className="schedule-axis"><span>midnight</span><span>noon</span><span>midnight</span></div></div>
        <div className="drawer-note"><Sparkles size={16} /><span>Overnight windows work too — try 10pm to 6am for a night shift.</span></div>
      </aside>
    </div>
  )
}

function DesktopGrid({ rows, referenceCity, format, mode, onPromote, onRemove }: { rows: CityRow[]; referenceCity: City; format: TimeFormat; mode: Mode; onPromote: (id: string) => void; onRemove: (id: string) => void }) {
  return (
    <div className="desktop-grid" style={{ '--city-columns': `minmax(210px, 1.25fr) repeat(24, minmax(31px, 1fr)) 44px` } as React.CSSProperties}>
      <div className="grid-corner"><span>Reference day</span><strong>{referenceCity.name}</strong></div>
      {Array.from({ length: 24 }, (_, hour) => <div key={hour} className={`grid-hour-head ${hour === 12 ? 'grid-hour-head--noon' : ''}`}><span>{formatHour(hour, format)}</span></div>)}
      <div className="grid-action-head"><span>EDIT</span></div>
      {rows.map((row, index) => (
        <div className="grid-row" key={row.city.id}>
          <div className={`city-cell ${index === 0 ? 'city-cell--reference' : ''}`}>
            <div className="city-leading"><span className="city-avatar" style={{ backgroundColor: row.city.accent }}>{row.city.name.charAt(0)}</span><div className="city-meta"><button className="city-name-button" onClick={() => onPromote(row.city.id)} title={index === 0 ? 'Reference city' : `Make ${row.city.name} the reference city`}>{row.city.name}</button><span>{countryFlag(row.city.countryCode)} {row.city.country}</span></div></div>
            {index === 0 ? <span className="ref-badge">REF</span> : <span className="city-offset">{formatOffset(row.offset)}</span>}
          </div>
          {row.cells.map((cell, hour) => <HourCell key={`${row.city.id}-${hour}`} cell={cell} hour={hour} format={format} />)}
          <div className="row-action"><button className="remove-button" onClick={() => onRemove(row.city.id)} disabled={rows.length === 1} aria-label={`Remove ${row.city.name}`} title={rows.length === 1 ? 'Keep at least one city' : `Remove ${row.city.name}`}><Minus size={15} /></button></div>
        </div>
      ))}
      <div className="grid-footer-spacer" /><div className="grid-footer-note" style={{ gridColumn: '2 / span 24' }}><span className="footer-dash" /> reference city's day · each cell is one hour</div><div />
    </div>
  )
}

function MobileGrid({ rows, referenceCity, format, onPromote, onRemove }: { rows: CityRow[]; referenceCity: City; format: TimeFormat; onPromote: (id: string) => void; onRemove: (id: string) => void }) {
  return (
    <div className="mobile-grid" aria-label="Mobile timezone grid">
      <div className="mobile-grid-head"><div className="mobile-hour-corner"><span>HOUR</span><strong>{referenceCity.name}</strong></div>{rows.map((row, index) => <div className={`mobile-city-head ${index === 0 ? 'mobile-city-head--reference' : ''}`} key={row.city.id}><span className="city-avatar" style={{ backgroundColor: row.city.accent }}>{row.city.name.charAt(0)}</span><button onClick={() => onPromote(row.city.id)}>{row.city.name}</button>{index === 0 ? <span className="ref-badge">REF</span> : <span className="city-offset">{formatOffset(row.offset)}</span>}<button className="mobile-remove" onClick={() => onRemove(row.city.id)} disabled={rows.length === 1} aria-label={`Remove ${row.city.name}`}><X size={13} /></button></div>)}</div>
      {Array.from({ length: 24 }, (_, hour) => <div className="mobile-grid-row" key={hour}><div className="mobile-hour-label"><strong>{formatHour(hour, format)}</strong><span>{hour === 0 ? 'start' : hour === 12 ? 'noon' : ''}</span></div>{rows.map((row) => <HourCell key={`${row.city.id}-${hour}`} cell={row.cells[hour]} hour={hour} format={format} />)}</div>)}
    </div>
  )
}

export default function App() {
  const [state, setState] = useState<AppState>(readStoredState)
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [now] = useState(() => new Date())

  useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state))
  }, [state])

  useEffect(() => {
    document.title = 'GPT-5.6 Luna'
  }, [])

  const cities = useMemo(() => state.cityIds.map(getCity).filter((city): city is City => Boolean(city)), [state.cityIds])
  const referenceCity = cities[0] ?? CITIES[0]
  const offsets = useMemo(() => new Map(cities.map((city) => [city.id, getOffsetMinutes(city.timezone, now)])), [cities, now])
  const referenceOffset = offsets.get(referenceCity.id) ?? getOffsetMinutes(referenceCity.timezone, now)

  const overlapByCity = useMemo(() => {
    const map = new Map<string, Set<number>>()
    if (state.mode === 'meeting') {
      const hours = new Set<number>()
      for (let hour = 0; hour < 24; hour += 1) {
        const everyoneAwake = cities.every((city) => {
          const offset = offsets.get(city.id) ?? 0
          const localHour = Math.floor((((hour * 60 + offset - referenceOffset) % 1440) + 1440) % 1440 / 60)
          return isAwake(localHour, state.wakeHour, state.sleepHour)
        })
        if (everyoneAwake) hours.add(hour)
      }
      map.set('meeting', hours)
      cities.forEach((city) => map.set(city.id, new Set(hours)))
      return map
    }

    const referenceAwake = new Set<number>()
    for (let hour = 0; hour < 24; hour += 1) {
      const localHour = Math.floor((((hour * 60) % 1440) + 1440) % 1440 / 60)
      if (isAwake(localHour, state.wakeHour, state.sleepHour)) referenceAwake.add(hour)
    }
    const unionForReference = new Set<number>()
    map.set(referenceCity.id, unionForReference)
    cities.filter((city) => city.id !== referenceCity.id).forEach((city) => {
      const offset = offsets.get(city.id) ?? 0
      const overlap = new Set<number>()
      for (let hour = 0; hour < 24; hour += 1) {
        const localHour = Math.floor((((hour * 60 + offset - referenceOffset) % 1440) + 1440) % 1440 / 60)
        if (referenceAwake.has(hour) && isAwake(localHour, state.wakeHour, state.sleepHour)) {
          overlap.add(hour)
          unionForReference.add(hour)
        }
      }
      map.set(city.id, overlap)
    })
    return map
  }, [cities, offsets, referenceCity.id, referenceOffset, state.mode, state.sleepHour, state.wakeHour])

  const rows = useMemo<CityRow[]>(() => cities.map((city) => ({
    city,
    offset: offsets.get(city.id) ?? 0,
    overlapHours: overlapByCity.get(city.id) ?? new Set<number>(),
    cells: getCityCellMap(city, referenceCity, offsets, state.wakeHour, state.sleepHour, overlapByCity.get(city.id) ?? new Set<number>(), state.timeFormat),
  })), [cities, offsets, overlapByCity, referenceCity, state.sleepHour, state.timeFormat, state.wakeHour])

  const updateState = (next: Partial<AppState>) => setState((current) => ({ ...current, ...next }))
  const addCity = (cityId: string) => setState((current) => current.cityIds.includes(cityId) ? current : { ...current, cityIds: [...current.cityIds, cityId] })
  const removeCity = (cityId: string) => setState((current) => current.cityIds.length === 1 ? current : { ...current, cityIds: current.cityIds.filter((id) => id !== cityId) })
  const promoteCity = (cityId: string) => setState((current) => ({ ...current, cityIds: [cityId, ...current.cityIds.filter((id) => id !== cityId)] }))

  return (
    <div className="app-shell">
      <div className="ambient-shape ambient-shape--one" />
      <div className="ambient-shape ambient-shape--two" />
      <header className="topbar">
        <div className="wordmark"><span className="wordmark-mark"><Globe2 size={15} /></span><span>LUNA / CLOCKWORK</span></div>
        <div className="topbar-status"><span className="live-dot" /> LIVE OFFSET DATA <span className="topbar-divider" /> {getTodayLabel(now)}</div>
      </header>

      <main className="main-content">
        <section className="hero">
          <div className="hero-copy"><p className="eyebrow"><span className="eyebrow-line" /> Distributed work, aligned</p><h1>GPT-5.6 Luna</h1><p className="hero-subtitle">Find the hour where your team lines up<span className="hero-period">.</span></p><p className="hero-description">A calm way to spot shared awake time across the cities your workday touches.</p></div>
          <div className="hero-signal"><div className="signal-orbit"><span className="signal-sun"><SunMedium size={20} /></span><span className="signal-dot signal-dot--a" /><span className="signal-dot signal-dot--b" /><span className="signal-dot signal-dot--c" /></div><div><span className="signal-label">RIGHT NOW</span><strong>{cities.length} {cities.length === 1 ? 'city' : 'cities'} in view</strong></div></div>
        </section>

        <section className="control-deck" aria-label="Comparison controls">
          <div className="mode-control"><span className="control-label">VIEW</span><div className="mode-toggle" role="group" aria-label="Comparison mode"><button className={state.mode === 'meeting' ? 'active' : ''} onClick={() => updateState({ mode: 'meeting' })}><span className="mode-icon mode-icon--meeting"><Sparkles size={13} /></span>Meeting</button><button className={state.mode === 'base' ? 'active' : ''} onClick={() => updateState({ mode: 'base' })}><span className="mode-icon mode-icon--base"><ArrowRight size={13} /></span>Base</button></div><span className="mode-description">{modeDescription(state.mode)}</span></div>
          <div className="control-actions"><span className="window-badge"><span className="window-dot" /> {formatHour(state.wakeHour, state.timeFormat)} — {formatHour(state.sleepHour, state.timeFormat)} awake</span><button className="settings-button" onClick={() => setSettingsOpen(true)}><Settings2 size={16} /> Schedule settings</button></div>
        </section>

        <OverlapSummary mode={state.mode} referenceCity={referenceCity} rows={rows} overlapByCity={overlapByCity} cityIds={state.cityIds} format={state.timeFormat} />

        <section className="cities-section">
          <div className="section-heading"><div><p className="eyebrow">Your clock map</p><h2>Compare cities <span>{String(cities.length).padStart(2, '0')}</span></h2></div><div className="section-heading-actions"><span className="reference-note"><span className="ref-dot" /> Click a city name to make it the reference</span><CityPicker selectedIds={state.cityIds} onAdd={addCity} /></div></div>
          <div className="grid-card"><div className="grid-card-top"><div className="grid-card-title"><span className="grid-card-icon"><Clock3 size={16} /></span><div><strong>Day alignment</strong><span>Each column is one hour in {referenceCity.name}</span></div></div><div className="grid-legend"><span><i className="legend-swatch legend-swatch--sleeping" /> Sleeping</span><span><i className="legend-swatch legend-swatch--awake" /> Awake</span><span><i className="legend-swatch legend-swatch--overlap" /> Overlap</span></div></div><DesktopGrid rows={rows} referenceCity={referenceCity} format={state.timeFormat} mode={state.mode} onPromote={promoteCity} onRemove={removeCity} /><MobileGrid rows={rows} referenceCity={referenceCity} format={state.timeFormat} onPromote={promoteCity} onRemove={removeCity} /></div>
          <div className="grid-footnote"><span className="footnote-icon"><Sparkles size={13} /></span><span>Green cells = everyone awake<span className="footnote-separator">·</span>UTC offsets reflect today, including DST</span></div>
        </section>
      </main>

      <footer className="page-footer"><span>Built for the spaces between <em>“what time works?”</em> and <em>“see you there.”</em></span><span>GPT-5.6 Luna <span className="footer-dot">•</span> Clockwork utility</span></footer>
      {settingsOpen && <SettingsDrawer state={state} onChange={updateState} onClose={() => setSettingsOpen(false)} />}
    </div>
  )
}

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  font-family: 'DM Sans', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  color: #27322e;
  background: #f3f5ef;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #27322e;
  --ink-soft: #68756c;
  --ink-faint: #9ba79d;
  --paper: #fbfcf8;
  --paper-deep: #eef1e9;
  --line: #dce2d8;
  --line-soft: #e7ebe3;
  --green: #0e7f68;
  --green-bright: #9ce5bc;
  --green-wash: #d9f4df;
  --green-deep: #084f43;
  --orange: #df9a58;
  --yellow-wash: #fff3d6;
  --shadow: 0 24px 80px rgba(47, 75, 58, .10);
}

* { box-sizing: border-box; }
html { min-width: 320px; background: #f3f5ef; }
body { margin: 0; min-width: 320px; min-height: 100vh; }
button, input, select { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid rgba(14, 127, 104, .35); outline-offset: 3px; }

.app-shell { min-height: 100vh; overflow: hidden; position: relative; background: linear-gradient(145deg, #f5f6f0 0%, #f3f5ef 55%, #edf3ee 100%); }
.ambient-shape { position: absolute; pointer-events: none; filter: blur(1px); opacity: .48; }
.ambient-shape--one { width: 370px; height: 370px; top: -185px; right: -75px; border-radius: 48% 52% 54% 46%; background: #dfefda; transform: rotate(25deg); }
.ambient-shape--two { width: 260px; height: 260px; top: 740px; left: -155px; border-radius: 50%; background: #f9e9d6; opacity: .4; }

.topbar, .main-content, .page-footer { position: relative; z-index: 1; }
.topbar { max-width: 1440px; margin: 0 auto; padding: 28px 52px 0; display: flex; justify-content: space-between; align-items: center; }
.wordmark { display: flex; align-items: center; gap: 10px; color: var(--green-deep); font-family: 'DM Mono', monospace; letter-spacing: .14em; font-size: 10px; font-weight: 500; }
.wordmark-mark { display: grid; place-items: center; width: 27px; height: 27px; border: 1px solid #a8d0b4; color: var(--green); border-radius: 9px 4px 9px 4px; transform: rotate(-7deg); }
.wordmark-mark svg { transform: rotate(7deg); }
.topbar-status { display: flex; align-items: center; gap: 9px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: .1em; }
.live-dot, .window-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 3px rgba(14, 127, 104, .12); }
.topbar-divider { width: 1px; height: 13px; background: var(--line); margin: 0 5px; }

.main-content { max-width: 1440px; margin: 0 auto; padding: 78px 52px 66px; }
.hero { display: flex; justify-content: space-between; gap: 44px; align-items: end; padding-bottom: 42px; }
.hero-copy { max-width: 690px; }
.eyebrow { margin: 0 0 14px; color: var(--green); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; letter-spacing: .16em; text-transform: uppercase; }
.eyebrow-line { display: inline-block; width: 26px; height: 1px; background: currentColor; vertical-align: middle; margin-right: 9px; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 11px; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: clamp(43px, 6vw, 82px); font-weight: 600; letter-spacing: -.075em; line-height: .98; }
.hero-subtitle { margin: 0; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: clamp(22px, 2.45vw, 35px); font-weight: 500; letter-spacing: -.055em; line-height: 1.1; }
.hero-period { color: var(--green); }
.hero-description { max-width: 420px; margin: 20px 0 0; color: var(--ink-soft); font-size: 14px; line-height: 1.65; }
.hero-signal { display: flex; align-items: center; gap: 16px; min-width: 205px; padding: 17px 18px 17px 15px; border: 1px solid rgba(166, 190, 168, .7); border-radius: 12px 5px 12px 5px; background: rgba(251, 252, 248, .62); box-shadow: 0 10px 32px rgba(56, 92, 61, .05); }
.signal-orbit { position: relative; width: 57px; height: 57px; border: 1px dashed #abd4af; border-radius: 50%; transform: rotate(-16deg); }
.signal-orbit::after { content: ''; position: absolute; inset: 7px; border: 1px solid #d4e7d0; border-radius: 50%; }
.signal-sun { position: absolute; inset: 18px; display: grid; place-items: center; border-radius: 50%; color: #9e6e35; background: #f7d897; transform: rotate(16deg); }
.signal-dot { position: absolute; width: 6px; height: 6px; border-radius: 50%; background: var(--green); }
.signal-dot--a { top: 2px; left: 27px; }
.signal-dot--b { top: 38px; left: 1px; background: #d89263; }
.signal-dot--c { top: 37px; right: 2px; background: #a78bd1; }
.signal-label { display: block; margin-bottom: 4px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .12em; }
.hero-signal strong { display: block; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: 15px; letter-spacing: -.02em; }

.control-deck { display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 76px; padding: 15px 18px 15px 20px; border: 1px solid var(--line); border-radius: 15px 5px 15px 5px; background: rgba(251, 252, 248, .76); box-shadow: 0 8px 32px rgba(48, 75, 59, .04); }
.mode-control { display: flex; align-items: center; gap: 14px; min-width: 0; }
.control-label { color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .13em; }
.mode-toggle { display: flex; gap: 3px; padding: 3px; border-radius: 9px; background: var(--paper-deep); }
.mode-toggle button { display: flex; align-items: center; gap: 7px; padding: 8px 12px; border: 0; border-radius: 7px; color: var(--ink-soft); background: transparent; cursor: pointer; font-size: 12px; font-weight: 600; transition: background .2s ease, color .2s ease, box-shadow .2s ease; }
.mode-toggle button.active { color: var(--green-deep); background: var(--paper); box-shadow: 0 2px 8px rgba(55, 82, 62, .10); }
.mode-icon { display: grid; place-items: center; width: 19px; height: 19px; border-radius: 6px; }
.mode-icon--meeting { color: #8b693d; background: #fae7bd; }
.mode-icon--base { color: #6170a0; background: #e1e8ff; }
.mode-description { color: var(--ink-faint); font-size: 12px; white-space: nowrap; }
.control-actions { display: flex; align-items: center; gap: 13px; }
.window-badge { display: inline-flex; align-items: center; gap: 8px; color: var(--ink-soft); font-family: 'DM Mono', monospace; font-size: 10px; white-space: nowrap; }
.settings-button, .add-city-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; border: 1px solid #b8cec0; border-radius: 7px 4px 7px 4px; color: var(--green-deep); background: #f7fbf4; cursor: pointer; font-size: 12px; font-weight: 600; transition: transform .2s ease, background .2s ease, border-color .2s ease; }
.settings-button { padding: 10px 13px; }
.settings-button:hover, .add-city-button:hover { border-color: var(--green); background: #eff9ed; transform: translateY(-1px); }

.summary-card { position: relative; display: flex; align-items: center; gap: 15px; min-height: 96px; margin-top: 18px; padding: 16px 20px; border: 1px solid #bee0c7; border-radius: 13px 5px 13px 5px; background: linear-gradient(110deg, rgba(233, 249, 232, .92), rgba(249, 251, 240, .84)); }
.summary-card--warning { border-color: #e8cf9b; background: linear-gradient(110deg, #fff5dc, #fbfaef); }
.summary-card--quiet { border-color: var(--line); background: rgba(251, 252, 248, .62); }
.summary-icon { display: grid; place-items: center; width: 39px; height: 39px; flex: 0 0 auto; border-radius: 9px 4px 9px 4px; color: var(--green-deep); background: var(--green-bright); }
.summary-card--warning .summary-icon { color: #865f2b; background: #f7d897; }
.summary-card--quiet .summary-icon { color: var(--ink-soft); background: var(--paper-deep); }
.summary-main { min-width: 0; }
.summary-kicker { margin: 0 0 5px; color: var(--ink-soft); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .1em; text-transform: uppercase; }
.summary-line { display: flex; align-items: baseline; gap: 7px; color: var(--ink); font-size: 13px; }
.summary-line strong { color: var(--green-deep); font-family: 'Space Grotesk', sans-serif; font-size: 25px; letter-spacing: -.06em; }
.summary-card--warning .summary-line strong { color: #9c672b; }
.summary-copy, .warning-copy { margin: 0; color: var(--ink-soft); font-size: 13px; }
.warning-copy { margin-top: 8px; font-size: 12px; }
.range-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 9px; }
.range-pill { display: inline-flex; align-items: center; padding: 5px 8px; border: 1px solid #abd6b7; border-radius: 5px; color: var(--green-deep); background: rgba(255, 255, 255, .54); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; }
.range-pill--small { padding: 4px 7px; font-size: 9px; }
.summary-side-stat { display: flex; flex-direction: column; gap: 4px; margin-left: auto; padding-left: 20px; border-left: 1px solid #c9dfcd; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .1em; text-align: right; }
.summary-side-stat strong { color: var(--ink-soft); font-family: 'DM Sans', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0; }
.summary-arrow { margin-left: auto; color: var(--ink-faint); }

.base-summary { margin-top: 18px; overflow: hidden; border: 1px solid #d5dce4; border-radius: 13px 5px 13px 5px; background: rgba(249, 251, 252, .72); }
.base-summary-heading { display: flex; justify-content: space-between; gap: 24px; align-items: center; padding: 16px 20px 13px; border-bottom: 1px solid #e0e5e8; }
.base-summary-copy { margin: 0; color: var(--ink-soft); font-size: 13px; }
.base-summary-ref { display: inline-flex; align-items: center; gap: 7px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 10px; white-space: nowrap; }
.ref-dot { display: inline-block; width: 7px; height: 7px; border-radius: 2px; background: #8ba6dd; transform: rotate(45deg); }
.base-summary-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(270px, 1fr)); }
.base-summary-row { display: flex; flex-direction: column; gap: 8px; min-height: 77px; padding: 13px 20px; border-right: 1px solid #e0e5e8; border-bottom: 1px solid #e0e5e8; }
.base-summary-row:nth-child(3n) { border-right: 0; }
.base-summary-row--warning { background: #fffaf0; }
.base-city-label { display: flex; align-items: center; gap: 7px; color: var(--ink); font-size: 12px; }
.city-swatch { width: 7px; height: 7px; border-radius: 2px; transform: rotate(45deg); }
.base-summary-detail { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; color: var(--green-deep); font-family: 'DM Mono', monospace; font-size: 10px; }
.base-warning-text { color: #9c7444; font-size: 11px; }

.cities-section { margin-top: 47px; }
.section-heading { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 16px; }
.section-heading .eyebrow { margin-bottom: 9px; }
h2 { margin-bottom: 0; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: 25px; font-weight: 600; letter-spacing: -.055em; }
h2 span { display: inline-block; margin-left: 5px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 500; letter-spacing: 0; vertical-align: middle; }
.section-heading-actions { display: flex; align-items: center; gap: 18px; }
.reference-note { display: inline-flex; align-items: center; gap: 8px; color: var(--ink-faint); font-size: 11px; }
.add-city-button { padding: 10px 12px; }
.picker-wrap { position: relative; }
.rotate-180 { transform: rotate(180deg); }
.city-picker { position: absolute; z-index: 20; top: calc(100% + 9px); right: 0; width: 306px; max-height: 395px; overflow: hidden; border: 1px solid var(--line); border-radius: 11px 4px 11px 4px; background: var(--paper); box-shadow: 0 20px 45px rgba(37, 59, 44, .16); }
.picker-search { display: flex; align-items: center; gap: 8px; padding: 12px 14px; border-bottom: 1px solid var(--line-soft); color: var(--ink-faint); }
.picker-search input { width: 100%; border: 0; outline: 0; color: var(--ink); background: transparent; font-size: 12px; }
.picker-search input::placeholder { color: var(--ink-faint); }
.picker-list { max-height: 332px; overflow-y: auto; padding: 8px; }
.picker-region-label { padding: 9px 8px 5px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .12em; text-transform: uppercase; }
.picker-option { width: 100%; display: flex; align-items: center; gap: 9px; padding: 9px 8px; border: 0; border-radius: 6px; color: var(--ink); background: transparent; cursor: pointer; text-align: left; transition: background .15s ease; }
.picker-option:hover { background: var(--paper-deep); }
.picker-option > span:nth-child(2) { display: flex; flex: 1; flex-direction: column; gap: 1px; }
.picker-option strong { font-size: 12px; font-weight: 600; }
.picker-option small { color: var(--ink-faint); font-size: 10px; }
.picker-option > svg { color: var(--green); }
.picker-flag { width: 21px; font-size: 15px; }
.picker-empty { padding: 24px 9px; margin: 0; color: var(--ink-soft); font-size: 12px; text-align: center; }

.grid-card { overflow: hidden; border: 1px solid var(--line); border-radius: 14px 5px 14px 5px; background: rgba(251, 252, 248, .76); box-shadow: var(--shadow); }
.grid-card-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 15px 18px; border-bottom: 1px solid var(--line); }
.grid-card-title { display: flex; align-items: center; gap: 10px; }
.grid-card-icon { display: grid; place-items: center; width: 31px; height: 31px; color: var(--green); border-radius: 7px; background: var(--green-wash); }
.grid-card-title > div { display: flex; flex-direction: column; gap: 2px; }
.grid-card-title strong { color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: 13px; letter-spacing: -.02em; }
.grid-card-title span { color: var(--ink-faint); font-size: 10px; }
.grid-legend { display: flex; align-items: center; gap: 15px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; }
.grid-legend span { display: inline-flex; align-items: center; gap: 6px; }
.legend-swatch { display: inline-block; width: 12px; height: 12px; border-radius: 3px; }
.legend-swatch--sleeping { border: 1px solid #e3e8df; background: #edf0eb; }
.legend-swatch--awake { border: 1px solid #dce2d8; background: #fbfcf8; }
.legend-swatch--overlap { border: 1px solid #83c999; background: var(--green-bright); }

.desktop-grid { display: grid; grid-template-columns: var(--city-columns); overflow-x: auto; }
.grid-corner, .grid-hour-head, .grid-action-head { min-height: 46px; border-bottom: 1px solid var(--line); background: #f6f8f2; }
.grid-corner { display: flex; flex-direction: column; justify-content: center; gap: 3px; padding: 7px 14px; position: sticky; left: 0; z-index: 3; border-right: 1px solid var(--line); }
.grid-corner span { color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .1em; text-transform: uppercase; }
.grid-corner strong { color: var(--ink-soft); font-size: 11px; font-weight: 600; }
.grid-hour-head { display: grid; place-items: center; min-width: 31px; border-right: 1px solid var(--line-soft); color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; }
.grid-hour-head--noon { color: var(--green); background: #eef7ee; }
.grid-action-head { display: grid; place-items: center; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .1em; }
.grid-row { display: contents; }
.city-cell { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 76px; padding: 11px 12px 11px 14px; position: sticky; left: 0; z-index: 2; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); background: rgba(251, 252, 248, .97); }
.city-cell--reference { background: #f5f9f2; }
.city-leading { display: flex; align-items: center; min-width: 0; gap: 9px; }
.city-avatar { display: grid; place-items: center; width: 27px; height: 27px; flex: 0 0 auto; border-radius: 9px 4px 9px 4px; color: #fff; font-family: 'Space Grotesk', sans-serif; font-size: 12px; font-weight: 600; box-shadow: inset 0 -2px 0 rgba(0, 0, 0, .08); }
.city-meta { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.city-name-button { overflow: hidden; padding: 0; border: 0; color: var(--ink); background: transparent; cursor: pointer; font-size: 12px; font-weight: 700; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.city-name-button:hover { color: var(--green); text-decoration: underline; text-decoration-color: #a8d8b4; text-underline-offset: 3px; }
.city-meta span { overflow: hidden; color: var(--ink-faint); font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.ref-badge { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; padding: 4px 5px; border: 1px solid #a5c6ae; border-radius: 4px; color: var(--green-deep); background: #e4f4e2; font-family: 'DM Mono', monospace; font-size: 8px; font-weight: 500; letter-spacing: .05em; }
.city-offset { flex: 0 0 auto; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; }
.hour-cell { display: flex; align-items: center; justify-content: center; gap: 4px; min-width: 31px; min-height: 76px; padding: 5px 2px; border-right: 1px solid var(--line-soft); border-bottom: 1px solid var(--line); color: var(--ink-soft); font-family: 'DM Mono', monospace; font-size: 9px; white-space: nowrap; transition: background .16s ease, color .16s ease; }
.hour-cell.sleeping { color: #b4beb4; background: #edf0eb; }
.hour-cell.awake { color: var(--ink-soft); background: #fbfcf8; }
.hour-cell.overlap { color: var(--green-deep); background: var(--green-bright); font-weight: 500; box-shadow: inset 0 0 0 2px #81cc9c; }
.hour-cell:hover { position: relative; z-index: 1; box-shadow: inset 0 0 0 2px rgba(39, 50, 46, .35); }
.hour-cell.overlap:hover { box-shadow: inset 0 0 0 2px var(--green-deep); }
.row-action { display: grid; place-items: center; min-height: 76px; border-bottom: 1px solid var(--line); background: rgba(251, 252, 248, .76); }
.remove-button, .icon-button, .mobile-remove { display: grid; place-items: center; padding: 0; border: 0; border-radius: 5px; color: var(--ink-faint); background: transparent; cursor: pointer; }
.remove-button { width: 25px; height: 25px; }
.remove-button:hover:not(:disabled), .icon-button:hover, .mobile-remove:hover:not(:disabled) { color: #b15f54; background: #fae9e4; }
.remove-button:disabled, .mobile-remove:disabled { cursor: not-allowed; opacity: .3; }
.grid-footer-spacer, .grid-footer-note, .desktop-grid > div:last-child { min-height: 31px; background: #f6f8f2; }
.grid-footer-spacer { border-right: 1px solid var(--line); }
.grid-footer-note { display: flex; align-items: center; gap: 7px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .03em; }
.footer-dash { width: 10px; height: 1px; background: #9abda0; }
.mobile-grid { display: none; }
.grid-footnote { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 13px 15px 14px; color: var(--ink-soft); font-size: 11px; }
.footnote-icon { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; color: var(--green); background: var(--green-wash); }
.footnote-separator { padding: 0 8px; color: #b4c0b4; }

.page-footer { display: flex; justify-content: space-between; gap: 20px; max-width: 1440px; margin: 0 auto; padding: 0 52px 28px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .03em; }
.page-footer em { color: var(--ink-soft); font-family: 'DM Sans', sans-serif; font-style: normal; font-size: 10px; }
.footer-dot { padding: 0 6px; color: var(--green); }

.drawer-layer { position: fixed; z-index: 50; inset: 0; display: flex; justify-content: flex-end; padding: 14px; background: rgba(28, 42, 34, .25); backdrop-filter: blur(4px); }
.settings-drawer { width: min(380px, 100%); overflow-y: auto; padding: 28px; border: 1px solid #d7e1d6; border-radius: 15px 6px 15px 6px; background: #fbfcf8; box-shadow: 0 30px 90px rgba(28, 56, 39, .25); animation: slide-in .28s cubic-bezier(.2, .75, .25, 1); }
@keyframes slide-in { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
.drawer-header { display: flex; justify-content: space-between; gap: 20px; align-items: start; padding-bottom: 18px; border-bottom: 1px solid var(--line); }
.drawer-header .eyebrow { margin-bottom: 7px; }
.drawer-header h2 { font-size: 28px; }
.icon-button { width: 30px; height: 30px; border: 1px solid var(--line); }
.drawer-intro { margin: 18px 0 25px; color: var(--ink-soft); font-size: 13px; line-height: 1.6; }
.setting-block { margin-bottom: 19px; }
.setting-block label, .setting-label { display: block; margin-bottom: 8px; color: var(--ink-soft); font-size: 11px; font-weight: 700; }
.select-wrap { position: relative; display: flex; align-items: center; gap: 9px; padding: 11px 12px; border: 1px solid var(--line); border-radius: 7px 3px 7px 3px; color: var(--green); background: #f8faf5; }
.select-wrap select { width: 100%; appearance: none; border: 0; outline: 0; color: var(--ink); background: transparent; cursor: pointer; font-family: 'DM Mono', monospace; font-size: 12px; }
.select-wrap > svg:last-child { position: absolute; right: 12px; pointer-events: none; color: var(--ink-faint); }
.format-toggle { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 4px; border-radius: 7px; background: var(--paper-deep); }
.format-toggle button { padding: 9px; border: 0; border-radius: 5px; color: var(--ink-soft); background: transparent; cursor: pointer; font-family: 'DM Mono', monospace; font-size: 11px; }
.format-toggle button.active { color: var(--green-deep); background: var(--paper); box-shadow: 0 2px 7px rgba(55, 82, 62, .1); }
.schedule-preview { margin-top: 30px; padding: 14px; border: 1px solid #d3e3d1; border-radius: 9px 3px 9px 3px; background: #f1f8ee; }
.schedule-preview-top { display: flex; justify-content: space-between; gap: 10px; color: var(--ink-soft); font-size: 10px; }
.schedule-preview-top strong { color: var(--green-deep); font-family: 'DM Mono', monospace; font-size: 10px; }
.schedule-track { position: relative; height: 11px; margin: 17px 0 7px; overflow: hidden; border-radius: 6px; background: #dfe9da; }
.schedule-track::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0, transparent calc(12.5% - 1px), rgba(120, 154, 122, .2) calc(12.5% - 1px), rgba(120, 154, 122, .2) 12.5%); }
.schedule-track-fill { position: absolute; top: 2px; bottom: 2px; border-radius: 4px; background: var(--green); box-shadow: 0 1px 4px rgba(14, 127, 104, .32); }
.schedule-axis { display: flex; justify-content: space-between; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 8px; }
.drawer-note { display: flex; align-items: start; gap: 9px; margin-top: 22px; padding: 12px; border-radius: 7px; color: #886d41; background: #fff4dc; font-size: 11px; line-height: 1.45; }
.drawer-note svg { flex: 0 0 auto; color: #c3914e; }

@media (max-width: 1100px) {
  .topbar, .main-content, .page-footer { padding-left: 30px; padding-right: 30px; }
  .mode-description, .reference-note { display: none; }
  .city-cell { padding-left: 10px; padding-right: 8px; }
  .city-meta span { max-width: 95px; }
}

@media (max-width: 767px) {
  .topbar { padding: 19px 18px 0; }
  .topbar-status { font-size: 8px; letter-spacing: .06em; }
  .topbar-status .topbar-divider, .topbar-status { }
  .topbar-status { max-width: 150px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
  .main-content { padding: 52px 18px 48px; }
  .hero { display: block; padding-bottom: 28px; }
  h1 { font-size: 54px; }
  .hero-subtitle { max-width: 310px; font-size: 25px; }
  .hero-description { max-width: 300px; margin-top: 15px; font-size: 13px; }
  .hero-signal { display: none; }
  .control-deck { display: block; padding: 13px; }
  .mode-control { justify-content: space-between; gap: 8px; }
  .control-label { display: none; }
  .mode-toggle { flex: 1; }
  .mode-toggle button { flex: 1; justify-content: center; }
  .control-actions { justify-content: space-between; gap: 7px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line-soft); }
  .window-badge { font-size: 9px; }
  .settings-button { padding: 9px 10px; font-size: 11px; }
  .summary-card { align-items: flex-start; padding: 15px; }
  .summary-side-stat { display: none; }
  .summary-line { display: block; }
  .summary-line span { display: block; margin-top: 2px; }
  .base-summary-heading { display: block; padding: 15px; }
  .base-summary-ref { margin-top: 10px; }
  .base-summary-list { display: block; }
  .base-summary-row { min-height: 0; padding: 14px 15px; border-right: 0; }
  .section-heading { display: block; }
  .section-heading-actions { justify-content: space-between; margin-top: 14px; }
  .grid-card { overflow-x: auto; border-radius: 11px 4px 11px 4px; }
  .grid-card-top { min-width: 680px; padding: 13px 14px; }
  .grid-legend { gap: 10px; }
  .desktop-grid { display: none; }
  .mobile-grid { display: block; min-width: max-content; }
  .mobile-grid-head, .mobile-grid-row { display: grid; grid-template-columns: 96px; grid-auto-columns: 133px; grid-auto-flow: column; }
  .mobile-grid-head { position: sticky; top: 0; z-index: 5; }
  .mobile-hour-corner, .mobile-city-head { min-height: 102px; padding: 11px 9px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); background: #f6f8f2; }
  .mobile-hour-corner { display: flex; flex-direction: column; justify-content: end; gap: 4px; position: sticky; left: 0; z-index: 4; }
  .mobile-hour-corner span { color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .11em; }
  .mobile-hour-corner strong { max-width: 74px; color: var(--ink-soft); font-size: 10px; line-height: 1.1; }
  .mobile-city-head { display: flex; flex-direction: column; align-items: start; gap: 6px; position: relative; }
  .mobile-city-head--reference { background: #f0f8ee; }
  .mobile-city-head .city-avatar { width: 28px; height: 28px; margin-bottom: 2px; }
  .mobile-city-head > button:not(.mobile-remove) { max-width: 112px; overflow: hidden; padding: 0; border: 0; color: var(--ink); background: transparent; cursor: pointer; font-size: 11px; font-weight: 700; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
  .mobile-city-head .city-offset { margin-top: -1px; font-size: 8px; }
  .mobile-city-head .ref-badge { padding: 3px 4px; font-size: 7px; }
  .mobile-remove { position: absolute; top: 9px; right: 8px; width: 20px; height: 20px; }
  .mobile-grid-row { min-height: 65px; }
  .mobile-hour-label { display: flex; flex-direction: column; justify-content: center; gap: 3px; padding: 8px; position: sticky; left: 0; z-index: 2; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); background: rgba(251, 252, 248, .98); }
  .mobile-hour-label strong { color: var(--ink-soft); font-family: 'DM Mono', monospace; font-size: 10px; }
  .mobile-hour-label span { color: var(--green); font-family: 'DM Mono', monospace; font-size: 8px; text-transform: uppercase; }
  .mobile-grid-row .hour-cell { min-width: 133px; min-height: 65px; border-bottom: 1px solid var(--line); }
  .grid-footnote { min-width: 680px; justify-content: flex-start; padding-left: 14px; font-size: 10px; }
  .page-footer { display: block; padding: 0 18px 20px; font-size: 8px; line-height: 1.8; }
  .page-footer > span:last-child { display: block; }
  .drawer-layer { padding: 0; align-items: flex-end; }
  .settings-drawer { width: 100%; max-height: 91vh; padding: 24px 20px 26px; border-radius: 16px 16px 0 0; animation: sheet-in .28s cubic-bezier(.2, .75, .25, 1); }
  @keyframes sheet-in { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

tool_use_result.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  font-family: 'DM Sans', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  color: #27322e;
  background: #f3f5ef;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #27322e;
  --ink-soft: #68756c;
  --ink-faint: #9ba79d;
  --paper: #fbfcf8;
  --paper-deep: #eef1e9;
  --line: #dce2d8;
  --line-soft: #e7ebe3;
  --green: #0e7f68;
  --green-bright: #9ce5bc;
  --green-wash: #d9f4df;
  --green-deep: #084f43;
  --orange: #df9a58;
  --yellow-wash: #fff3d6;
  --shadow: 0 24px 80px rgba(47, 75, 58, .10);
}

* { box-sizing: border-box; }
html { min-width: 320px; background: #f3f5ef; }
body { margin: 0; min-width: 320px; min-height: 100vh; }
button, input, select { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid rgba(14, 127, 104, .35); outline-offset: 3px; }

.app-shell { min-height: 100vh; overflow: hidden; position: relative; background: linear-gradient(145deg, #f5f6f0 0%, #f3f5ef 55%, #edf3ee 100%); }
.ambient-shape { position: absolute; pointer-events: none; filter: blur(1px); opacity: .48; }
.ambient-shape--one { width: 370px; height: 370px; top: -185px; right: -75px; border-radius: 48% 52% 54% 46%; background: #dfefda; transform: rotate(25deg); }
.ambient-shape--two { width: 260px; height: 260px; top: 740px; left: -155px; border-radius: 50%; background: #f9e9d6; opacity: .4; }

.topbar, .main-content, .page-footer { position: relative; z-index: 1; }
.topbar { max-width: 1440px; margin: 0 auto; padding: 28px 52px 0; display: flex; justify-content: space-between; align-items: center; }
.wordmark { display: flex; align-items: center; gap: 10px; color: var(--green-deep); font-family: 'DM Mono', monospace; letter-spacing: .14em; font-size: 10px; font-weight: 500; }
.wordmark-mark { display: grid; place-items: center; width: 27px; height: 27px; border: 1px solid #a8d0b4; color: var(--green); border-radius: 9px 4px 9px 4px; transform: rotate(-7deg); }
.wordmark-mark svg { transform: rotate(7deg); }
.topbar-status { display: flex; align-items: center; gap: 9px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: .1em; }
.live-dot, .window-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 3px rgba(14, 127, 104, .12); }
.topbar-divider { width: 1px; height: 13px; background: var(--line); margin: 0 5px; }

.main-content { max-width: 1440px; margin: 0 auto; padding: 78px 52px 66px; }
.hero { display: flex; justify-content: space-between; gap: 44px; align-items: end; padding-bottom: 42px; }
.hero-copy { max-width: 690px; }
.eyebrow { margin: 0 0 14px; color: var(--green); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; letter-spacing: .16em; text-transform: uppercase; }
.eyebrow-line { display: inline-block; width: 26px; height: 1px; background: currentColor; vertical-align: middle; margin-right: 9px; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 11px; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: clamp(43px, 6vw, 82px); font-weight: 600; letter-spacing: -.075em; line-height: .98; }
.hero-subtitle { margin: 0; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: clamp(22px, 2.45vw, 35px); font-weight: 500; letter-spacing: -.055em; line-height: 1.1; }
.hero-period { color: var(--green); }
.hero-description { max-width: 420px; margin: 20px 0 0; color: var(--ink-soft); font-size: 14px; line-height: 1.65; }
.hero-signal { display: flex; align-items: center; gap: 16px; min-width: 205px; padding: 17px 18px 17px 15px; border: 1px solid rgba(166, 190, 168, .7); border-radius: 12px 5px 12px 5px; background: rgba(251, 252, 248, .62); box-shadow: 0 10px 32px rgba(56, 92, 61, .05); }
.signal-orbit { position: relative; width: 57px; height: 57px; border: 1px dashed #abd4af; border-radius: 50%; transform: rotate(-16deg); }
.signal-orbit::after { content: ''; position: absolute; inset: 7px; border: 1px solid #d4e7d0; border-radius: 50%; }
.signal-sun { position: absolute; inset: 18px; display: grid; place-items: center; border-radius: 50%; color: #9e6e35; background: #f7d897; transform: rotate(16deg); }
.signal-dot { position: absolute; width: 6px; height: 6px; border-radius: 50%; background: var(--green); }
.signal-dot--a { top: 2px; left: 27px; }
.signal-dot--b { top: 38px; left: 1px; background: #d89263; }
.signal-dot--c { top: 37px; right: 2px; background: #a78bd1; }
.signal-label { display: block; margin-bottom: 4px; color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .12em; }
.hero-signal strong { display: block; color: var(--ink); font-family: 'Space Grotesk', sans-serif; font-size: 15px; letter-spacing: -.02em; }

.control-deck { display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 76px; padding: 15px 18px 15px 20px; border: 1px solid var(--line); border-radius: 15px 5px 15px 5px; background: rgba(251, 252, 248, .76); box-shadow: 0 8px 32px rgba(48, 75, 59, .04); }
.mode-control { display: flex; align-items: center; gap: 14px; min-width: 0; }
.control-label { color: var(--ink-faint); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .13em; }
.mode-toggle { display: flex; gap: 3px; padding: 3px; border-radius: 9px; background: var(--paper-deep); }
.mode-toggle button { display: flex; align-items: center; gap: 7px; padding: 8px 12px; border: 0; border-radius: 7px; color: var(--ink-soft); background: transparent; cursor: pointer; font-size: 12px; font-weight: 600; transition: background .2s ease, color .2s ease, box-shadow .2s ease; }
.mode-toggle button.active { color: var(--green-deep); background: var(--paper); box-shadow: 0 2px 8px rgba(55, 82, 62, .10); }
.mode-icon { display: grid; place-items: center; width: 19px; height: 19px; border-radius: 6px; }
.mode-icon--meeting { color: #8b693d; background: #fae7bd; }
.mode-icon--base { color: #6170a0; background: #e1e8ff; }
.mode-description { color: var(--ink-faint); font-size: 12px; white-space: nowrap; }
.control-actions { display: flex; align-items: center; gap: 13px; }
.window-badge { display: inline-flex; align-items: center; gap: 8px; color: var(--ink-soft); font-family: 'DM Mono', monospace; font-size: 10px; white-space: nowrap; }
.settings-button, .add-city-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; border: 1px solid #b8cec0; border-radius: 7px 4px 7px 4px; color: var(--green-deep); background: #f7fbf4; cursor: pointer; font-size: 12px; font-weight: 600; transition: transform .2s ease, background .2s ease, border-color .2s ease; }
.settings-button { padding: 10px 13px; }
.settings-button:hover, .add-city-button:hover { border-color: var(--green); background: #eff9ed; transform: translateY(-1px); }

.summary-card { position: relative; display: flex; align-items: center; gap: 15px; min-height: 96px; margin-top: 18px; padding: 16px 20px; border: 1px solid #bee0c7; border-radius: 13px 5px 13px 5px; background: linear-gradient(110deg, rgba(233, 249, 232, .92), rgba(249, 251, 240, .84)); }
.summary-card--warning { border-color: #e8cf9b; background: linear-gradient(110deg, #fff5dc, #fbfaef); }
.summary-card--quiet { border-color: var(--line); background: rgba(251, 252, 248, .62); }
